const { z } = require("zod");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
const a = z.object({ name: z.string() });
const b = z.object({ age: z.number() }).refine((d) => d.age >= 18, { message: "Must be 18+" });
let merged;
try { merged = a.merge(b); } catch (e) { broken("a.merge(b) threw: " + e.message); }
const ok = merged.safeParse({ name: "n", age: 21 });
if (!ok.success) broken("valid input was rejected: " + JSON.stringify(ok.error.issues));
const r = merged.safeParse({ name: "n", age: 12 });
if (r.success) symptom("a.merge(b) dropped the refine() of the merged-in schema b, so age 12 was accepted");
if (!r.error.issues.some((i) => i.message === "Must be 18+")) broken("unexpected issues: " + JSON.stringify(r.error.issues));
console.log("OK: a.merge(b) keeps the refine() of b");

